package com.dukankhata.subscription;

import com.dukankhata.auth.User; import com.dukankhata.common.exception.ResourceNotFoundException; import com.dukankhata.shop.Shop; import com.dukankhata.shop.ShopRepository; import com.dukankhata.subscription.dto.*; import com.fasterxml.jackson.databind.JsonNode; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal; import java.math.RoundingMode; import java.time.Instant; import java.time.temporal.ChronoUnit; import java.util.*;

@Service public class SubscriptionService {
 private final SubscriptionPlanRepository plans; private final SubscriptionRepository subscriptions; private final SubscriptionPaymentRepository payments; private final WebhookEventRepository webhooks; private final ShopRepository shops; private final RazorpayClient razorpay; private final int trialDays; private final String webhookSecret;
 public SubscriptionService(SubscriptionPlanRepository plans,SubscriptionRepository subscriptions,SubscriptionPaymentRepository payments,WebhookEventRepository webhooks,ShopRepository shops,RazorpayClient razorpay,@Value("${subscription.trial-days:30}") int trialDays,@Value("${razorpay.webhook-secret:}") String webhookSecret){this.plans=plans;this.subscriptions=subscriptions;this.payments=payments;this.webhooks=webhooks;this.shops=shops;this.razorpay=razorpay;this.trialDays=trialDays;this.webhookSecret=webhookSecret;}
 @Transactional(readOnly=true) public List<PlanResponse> plans(){return plans.findAllByActiveTrueOrderByAmountAsc().stream().map(p->new PlanResponse(p.getId(),p.getCode(),p.getName(),p.getAmount(),p.getCurrency(),p.getDurationDays())).toList();}
 @Transactional public OrderResponse createOrder(User user,String code){SubscriptionPlan plan=plans.findByCodeAndActiveTrue(code.trim().toUpperCase()).orElseThrow(()->new ResourceNotFoundException("Subscription plan not found")); if(plan.getAmount().compareTo(BigDecimal.ZERO)<=0) throw new IllegalStateException("Subscription plan price is invalid");
  Shop shop=user.getShop(); String receipt="DK-"+shop.getId().toString().substring(0,8)+"-"+UUID.randomUUID().toString().substring(0,8); long paise=plan.getAmount().movePointRight(2).setScale(0,RoundingMode.HALF_UP).longValueExact(); JsonNode order=razorpay.createOrder(paise,plan.getCurrency(),receipt);
  SubscriptionPayment payment=new SubscriptionPayment(); payment.setShop(shop); payment.setPlan(plan); payment.setRazorpayOrderId(order.path("id").asText()); payment.setAmount(plan.getAmount()); payment.setCurrency(plan.getCurrency()); payment.setStatus("CREATED"); payments.save(payment);
  subscriptions.findTopByShopIdOrderByCreatedAtDesc(shop.getId()).ifPresent(s->{if(s.getStatus()==SubscriptionStatus.PAYMENT_PENDING)s.setStatus(SubscriptionStatus.CANCELLED);});
  Subscription sub=new Subscription(); sub.setShop(shop); sub.setPlan(plan); sub.setStatus(SubscriptionStatus.PAYMENT_PENDING); sub.setRazorpayOrderId(payment.getRazorpayOrderId()); subscriptions.save(sub); shop.setPlanStatus("PAYMENT_PENDING"); shops.save(shop);
  return new OrderResponse(razorpay.getKeyId(),payment.getRazorpayOrderId(),plan.getAmount(),plan.getCurrency(),plan.getCode(),plan.getName(),plan.getDurationDays(),payment.getId());
 }
 @Transactional public SubscriptionResponse verify(User user,VerifyPaymentRequest req){SubscriptionPayment p=payments.findByRazorpayOrderId(req.razorpayOrderId()).orElseThrow(()->new ResourceNotFoundException("Payment order not found")); if(!p.getShop().getId().equals(user.getShop().getId())) throw new IllegalStateException("Payment does not belong to this shop"); if(!razorpay.verifySignature(req.razorpayOrderId(),req.razorpayPaymentId(),req.razorpaySignature())) throw new IllegalStateException("Payment signature verification failed"); activate(p,req.razorpayPaymentId()); return current(user);}
 @Transactional public void processWebhook(String payload,String signature){if(webhookSecret.isBlank()) throw new IllegalStateException("Razorpay webhook secret is not configured"); if(!razorpay.verifyWebhookSignature(payload,signature,webhookSecret)) throw new IllegalStateException("Invalid webhook signature"); try{var mapper=new com.fasterxml.jackson.databind.ObjectMapper(); JsonNode root=mapper.readTree(payload); String eventId=root.path("id").asText(); String event=root.path("event").asText(); if(eventId.isBlank()) throw new IllegalArgumentException("Webhook event id is required"); if(webhooks.existsByProviderEventId(eventId)) return; WebhookEvent w=new WebhookEvent();w.setProviderEventId(eventId);w.setEventType(event);webhooks.save(w); if("payment.captured".equals(event)||"order.paid".equals(event)){String orderId=root.at("/payload/payment/entity/order_id").asText();String paymentId=root.at("/payload/payment/entity/id").asText(); if(orderId.isBlank()) orderId=root.at("/payload/order/entity/id").asText(); if(paymentId.isBlank()) paymentId=root.at("/payload/order/entity/payment_id").asText(); if(!orderId.isBlank()){String verifiedPaymentId=paymentId;payments.findByRazorpayOrderId(orderId).ifPresent(p->activate(p,verifiedPaymentId));}}}
 catch(Exception e){throw new IllegalArgumentException("Invalid Razorpay webhook payload",e);}}
 @Transactional(readOnly=true) public SubscriptionResponse current(User user){Subscription s=subscriptions.findTopByShopIdOrderByCreatedAtDesc(user.getShop().getId()).orElse(null); if(s==null){Instant end=user.getShop().getCreatedAt().plus(trialDays,ChronoUnit.DAYS); return new SubscriptionResponse("TRIAL","Free Trial",Instant.now().isAfter(end)?SubscriptionStatus.EXPIRED:SubscriptionStatus.TRIAL,user.getShop().getCreatedAt(),end,null);} if(s.getEndsAt()!=null&&Instant.now().isAfter(s.getEndsAt())&&s.getStatus()==SubscriptionStatus.ACTIVE){return new SubscriptionResponse(s.getPlan().getCode(),s.getPlan().getName(),SubscriptionStatus.EXPIRED,s.getStartsAt(),s.getEndsAt(),s.getRazorpayOrderId());} return new SubscriptionResponse(s.getPlan().getCode(),s.getPlan().getName(),s.getStatus(),s.getStartsAt(),s.getEndsAt(),s.getRazorpayOrderId());}
 private void activate(SubscriptionPayment p,String paymentId){p.setRazorpayPaymentId(paymentId);p.setStatus("CAPTURED");payments.save(p); Subscription s=subscriptions.findByRazorpayOrderId(p.getRazorpayOrderId()).orElseThrow(() -> new ResourceNotFoundException("Subscription order not found")); Instant start=Instant.now(); s.setStatus(SubscriptionStatus.ACTIVE);s.setStartsAt(start);s.setEndsAt(start.plus(p.getPlan().getDurationDays(),ChronoUnit.DAYS));s.setRazorpayPaymentId(paymentId);s.setRazorpayOrderId(p.getRazorpayOrderId());subscriptions.save(s);p.getShop().setPlanStatus("ACTIVE");shops.save(p.getShop());}
}
